PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investment_type (AVG(xsd:decimal(?dividends)) AS ?average_dividend_income)
WHERE {
  ?holding a ex:PortfolioHolding ;
           ex:investmentTypeLiteral ?investment_type ;
           ex:dividends ?dividends .
}
GROUP BY ?investment_type
ORDER BY DESC(?average_dividend_income)
LIMIT 1

