PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?preferredSector ?highestAllocationSector
WHERE {
  # Get the preferred sector from the investor's profile
  ex:INV001 ex:sectorFocus ?preferredSector.

  # Get the sector with the highest allocation percentage in their actual portfolio
  {
    SELECT ?sectorName AS ?highestAllocationSector (MAX(?allocationPct) AS ?maxAllocation)
    WHERE {
      ex:INV001 ex:hasHolding ?holding.
      ?holding ex:hasSector ?sector.
      ?sector ex:sectorName ?sectorName.
      ?holding ex:allocationPct ?allocationPct.
    }
  }
}
GROUP BY ?preferredSector

PREFIX ex: <http://example.org/kg#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?sectorFocus ?highestAllocatedSector
WHERE {
  ex:INV001 ex:sectorFocus ?sectorFocus .

  {
    SELECT (MAX(xsd:decimal(?totalInvestment)) AS ?maxTotalInvestment)
    WHERE {
      ?allocation a ex:SectorAllocation ;
                 ex:hasInvestor ex:INV001 ;
                 ex:totalInvestment ?totalInvestment .
    }
  }

  {
    SELECT ?highestAllocatedSector
    WHERE {
      ?allocation a ex:SectorAllocation ;
                 ex:hasInvestor ex:INV001 ;
                 ex:totalInvestment ?totalInvestment .
      FILTER(xsd:decimal(?totalInvestment) = ?maxTotalInvestment)
    }
  }
}

